"use client";

import { Avatar, Indicator, IndicatorProps } from '@mantine/core';

function Demo(props: IndicatorProps) {
  return (
    <Indicator {...props}>
      <Avatar
        size="lg"
        radius="sm"
        src="https://raw.githubusercontent.com/mantinedev/mantine/master/.demo/avatars/avatar-1.png"
      />
    </Indicator>
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent color={"blue"} position={"top-end"} radius={"xl"} size={10} disabled={false} withBorder={false} processing={false} />; }

"use client";

import { Avatar, Button, Indicator, Stack } from '@mantine/core';

import { useDisclosure } from '@mantine/hooks';

function Demo() {
  const [visible, { toggle }] = useDisclosure();

  return (
    <Stack align="center">
      <Indicator inline disabled={!visible} color="red" size={12}>
        <Avatar
          size="lg"
          radius="sm"
          src="https://raw.githubusercontent.com/mantinedev/mantine/master/.demo/avatars/avatar-5.png"
        />
      </Indicator>
      <Button onClick={toggle}>Toggle indicator</Button>
    </Stack>
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent  />; }

